const events = [
 {id:1,title:'Acoustic on the Green',category:'Music',day:17,time:'5:30–7:00 PM',location:'The Quad · near Denny Chimes',cost:0,atmosphere:'Relaxed',drop:true,act:false,art:'acoustic\nafter hours.',icon:'♫',host:'Campus Music Collective',description:'Take a study break with a mellow acoustic set on the lawn. Bring a blanket, settle in, and stay for a song or the whole evening.',access:'Outdoor lawn; paved paths nearby. Seating is bring-your-own.',arrival:'Meet beside the fictional SocialFinder welcome sign on the west side of Denny Chimes.'},
 {id:2,title:'Sunset Walk & Talk',category:'Outdoors',day:18,time:'4:30–5:30 PM',location:'Riverwalk · Manderson Landing',cost:0,atmosphere:'Relaxed',drop:false,act:false,art:'fresh air.\nfresh faces.',icon:'☀',host:'Fresh Air Club',description:'An easy-paced riverside walk with conversation prompts to make introductions feel natural. No hiking experience needed.',access:'Paved route with benches. Accessible pace and route available.',arrival:'Meet at the Manderson Landing entrance at 4:20 PM. The group leaves together at 4:30 PM.'},
 {id:3,title:'Board Games, New Names',category:'Games',day:19,time:'6:00–8:00 PM',location:'Student Center · Room 210',cost:0,atmosphere:'Social',drop:true,act:true,art:'your move.\nyour people.',icon:'⚄',host:'Tabletop Together',description:'Pull up a chair for easy-to-learn card and board games. Hosts will help you join a table, even if you come on your own.',access:'Elevator access; seated activity. Ask the demo host for a quieter table.',arrival:'Find the welcome table inside Room 210. Bring your ACT Card for the demo entry requirement.'},
 {id:4,title:'Clay & Conversation',category:'Arts',day:20,time:'3:00–4:30 PM',location:'Student Center · Craft Studio',cost:5,atmosphere:'Relaxed',drop:false,act:true,art:'make a little\nsomething.',icon:'✿',host:'Creative Campus Circle',description:'Shape a small clay keepsake while getting to know other students. All materials are included in the fictional $5 activity cost; no payment is collected here.',access:'Seated workstations; step-free studio access.',arrival:'Arrive by 2:50 PM for materials and introductions. Plan to stay for the guided workshop.'},
 {id:5,title:'Community Garden Morning',category:'Community',day:21,time:'10:00–11:30 AM',location:'Campus Garden · East entrance',cost:0,atmosphere:'Social',drop:true,act:false,art:'good roots.\ngreat company.',icon:'❋',host:'Growing Together',description:'Spend a low-pressure morning planting herbs and meeting students who care about a greener campus. Tools and gloves are provided.',access:'Outdoor gravel and grass; seated planting station available.',arrival:'Check in at the east entrance. Wear closed-toe shoes and bring water.'},
 {id:6,title:'Sunday Pick-up Volleyball',category:'Sports',day:22,time:'2:00–4:00 PM',location:'Student Recreation Center · Court 2',cost:0,atmosphere:'Energetic',drop:true,act:true,art:'all levels.\nall welcome.',icon:'◉',host:'Weekend Rec Crew',description:'Casual rotating teams with space for beginners. Join a game, cheer from the sidelines, or take a break whenever you need.',access:'Step-free entrance and accessible spectator seating.',arrival:'Bring your ACT Card and indoor athletic shoes. Meet the fictional host at Court 2.'}
];
const categories=['Music','Outdoors','Games','Arts','Community','Sports'];
const defaultState=()=>({saved:[],rsvps:[],together:[],prefs:{interests:[],atmosphere:'Any',budget:'Any'}});
let state=defaultState();
try{const p=JSON.parse(localStorage.getItem('socialfinder-v1'));if(p&&Array.isArray(p.saved)&&Array.isArray(p.rsvps)&&Array.isArray(p.together)&&p.prefs&&Array.isArray(p.prefs.interests)){state={saved:p.saved.filter(x=>events.some(e=>e.id===x)),rsvps:p.rsvps.filter(x=>events.some(e=>e.id===x)),together:p.together.filter(x=>events.some(e=>e.id===x)),prefs:{interests:p.prefs.interests.filter(x=>categories.includes(x)),atmosphere:['Any','Relaxed','Social','Energetic'].includes(p.prefs.atmosphere)?p.prefs.atmosphere:'Any',budget:['Any','Free'].includes(p.prefs.budget)?p.prefs.budget:'Any'}}}}catch{}
let filters={q:'',date:'Any',interest:'Any',cost:'Any',atmosphere:'Any'},planTab='all',activeEvent=null,opener=null;
const main=document.getElementById('main'),dialog=document.getElementById('event-dialog');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageAvailable=true;function persist(){try{localStorage.setItem('socialfinder-v1',JSON.stringify(state));storageAvailable=true}catch{storageAvailable=false}updateCount()}
function updateCount(){document.getElementById('plan-count').textContent=new Set([...state.saved,...state.rsvps,...state.together]).size}
let timer;function toast(message){const el=document.getElementById('toast');el.textContent=message+(storageAvailable?'':' Changes last for this visit only; browser storage is unavailable.');const localStatus=dialog.querySelector('#dialog-status');if(localStatus)localStatus.textContent=el.textContent;el.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>el.classList.remove('show'),3500)}
const money=e=>e.cost===0?'Free':`$${e.cost}`;
const weekday=e=>['Tue','Wed','Thu','Fri','Sat','Sun'][e.day-17];
function score(e){return (state.prefs.interests.includes(e.category)?3:0)+(state.prefs.atmosphere===e.atmosphere?2:0)+(state.prefs.budget==='Free'&&e.cost===0?1:0)}
function reason(e){const r=[];if(state.prefs.interests.includes(e.category))r.push(`${e.category.toLowerCase()} interest`);if(state.prefs.atmosphere===e.atmosphere)r.push(`${e.atmosphere.toLowerCase()} atmosphere`);if(state.prefs.budget==='Free'&&e.cost===0)r.push('free admission');return r.length?`Matches your ${r.join(' + ')}`:'Something different to explore'}
function poster(e,extra=''){return `<div class="poster ${e.category.toLowerCase()} ${extra}"><span class="art-label">${e.art}</span><span class="poster-icon" aria-hidden="true">${e.icon}</span></div>`}
function card(e,recommend=false){return `<article class="card"><div style="position:relative">${poster(e)}<span class="date-badge">NOV<b>${e.day}</b></span><button class="save" data-save="${e.id}" aria-label="${state.saved.includes(e.id)?'Unsave':'Save'} ${e.title}" aria-pressed="${state.saved.includes(e.id)}">${state.saved.includes(e.id)?'♥':'♡'}</button></div><div class="card-body"><span class="category">${e.category.toUpperCase()} · ${e.atmosphere.toUpperCase()}</span><button class="title-button" data-open="${e.id}"><h3>${e.title}</h3></button><p class="meta">◷ ${weekday(e)}, Nov ${e.day} · ${e.time}</p><p class="meta">⌖ ${e.location}</p><div class="chips">${state.together.includes(e.id)?'<span class="chip rose">Meetup demo</span>':''}<span class="chip">${money(e)}</span><span class="chip">${e.drop?'Drop in anytime':'Full session'}</span>${state.rsvps.includes(e.id)?'<span class="chip rose">RSVP in demo ✓</span>':''}</div>${calendarBadge(e)}${recommend?`<p class="recommendation">✧ ${reason(e)}</p>`:''}<div class="card-footer"><span>${e.act?'ACT Card needed':'No ACT Card needed'}</span><button data-open="${e.id}" aria-label="Details for ${e.title}">Details ↗</button></div></div></article>`}
function select(name,label,values,current){return `<label>${label}<select id="filter-${name}" data-filter="${name}">${values.map(([v,t])=>`<option value="${v}" ${v===current?'selected':''}>${t}</option>`).join('')}</select></label>`}
function filterUI(){return `<div class="filters"><label class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Search events, interests, or places…" aria-label="Search events" value="${esc(filters.q)}"></label><div class="filter-row">${select('date','WHEN',[['Any','Any date'],['Today','Today · Nov 17'],['Tomorrow','Tomorrow · Nov 18'],['Weekend','This weekend']],filters.date)}${select('interest','INTEREST',[['Any','All interests'],...categories.map(x=>[x,x])],filters.interest)}${select('cost','COST',[['Any','Any cost'],['Free','Free'],['Paid','Paid']],filters.cost)}${select('atmosphere','ATMOSPHERE',[['Any','Any atmosphere'],...['Relaxed','Social','Energetic'].map(x=>[x,x])],filters.atmosphere)}<button class="clear" id="clear">Reset filters ↺</button></div></div>`}
function filtered(){return events.filter(e=>(`${e.title} ${e.category} ${e.location} ${e.description}`.toLowerCase().includes(filters.q.trim().toLowerCase()))&&(filters.interest==='Any'||e.category===filters.interest)&&(filters.cost==='Any'||(filters.cost==='Free'?e.cost===0:e.cost>0))&&(filters.atmosphere==='Any'||e.atmosphere===filters.atmosphere)&&(filters.date==='Any'||(filters.date==='Today'?e.day===17:filters.date==='Tomorrow'?e.day===18:e.day>=21)))}
function empty(title,body,action=''){return `<div class="empty"><h3>${title}</h3><p>${body}</p>${action}</div>`}
function renderResults(){const rows=filtered();document.getElementById('results').innerHTML=rows.length?rows.map(e=>card(e)).join(''):empty('Nothing here just yet','Try another interest or clear a filter to see more of campus.','<button class="secondary" id="clear-empty">Clear all filters</button>');document.getElementById('result-count').textContent=`${rows.length} event${rows.length===1?'':'s'} to explore`}
function topLine(){return '<div class="topline"><span class="location">⌖ Tuscaloosa, Alabama</span><span>YOUR CAMPUS. A LITTLE CLOSER.</span></div>'}
function render(){const route=location.hash.slice(1)||'discover';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===route);if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});updateCount();
 if(route==='discover'){main.innerHTML=topLine()+`<section class="hero"><div class="hero-copy"><span class="eyebrow">LESS SCROLLING. MORE SHOWING UP.</span><h1>Your next good thing<br>is right here.</h1><p>Find your kind of campus events. Know the details.<br>Feel a little more at home.</p><a class="primary" href="#suggestions">Find something for me &nbsp; ↗</a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><span class="spark">✧</span><div class="ticket"><small>YOUR INVITATION TO</small><strong>a break.<br>a new friend.<br>a good story.</strong><div class="ticket-bottom">TUSCALOOSA &nbsp; · &nbsp; SEE YOU THERE ↗</div></div><div class="float-tag">✦ &nbsp; Come as you are.</div></div></section><div class="section-head"><div><h2>Find your kind of plans</h2><p>A few hours. A new connection. A reason to get out.</p></div><a href="#preferences">Tune your interests ↗</a></div>${filterUI()}<div class="results-info"><span id="result-count" role="status"></span><span>Sorted by date ↑</span></div><section class="grid" id="results" aria-label="Events"></section>`;renderResults();
 }else if(route==='suggestions'){const configured=state.prefs.interests.length||state.prefs.atmosphere!=='Any'||state.prefs.budget!=='Any';const sorted=[...events].sort((a,b)=>score(b)-score(a)||a.day-b.day);main.innerHTML=topLine()+`<div class="page-intro"><span class="eyebrow">A LITTLE MORE YOU</span><h1>Good plans, your way.</h1><p>Suggestions based on what you tell us you enjoy. Every event stays open to explore.</p><a class="secondary" href="#preferences">${configured?'Edit':'Choose'} your preferences ↗</a></div><div class="notice">${configured?'How these suggestions work: shared interests count most, followed by atmosphere and your free-event preference.':'Start with your interests to personalize this list. For now, explore all six demo events in date order.'} This is a simple preference-based demo, not AI or personality matching.</div><div class="section-head"><h2>${configured?'Picked around your preferences':'A place to start'}</h2><span class="meta">6 possibilities</span></div><section class="grid">${sorted.map(e=>card(e,!!configured)).join('')}</section>`;
 }else if(route==='calendar'){main.innerHTML=calendarPage();
 }else if(route==='plans'){const ids=planTab==='saved'?state.saved:planTab==='rsvp'?state.rsvps:[...new Set([...state.saved,...state.rsvps,...state.together])];const rows=events.filter(e=>ids.includes(e.id));main.innerHTML=topLine()+`<div class="page-intro"><span class="eyebrow">MAKE ROOM FOR SOMETHING GOOD</span><h1>Your campus calendar,<br>without the chaos.</h1><p>Keep the maybes. Plan the yeses. Your saved events and demo RSVPs live here.</p></div>${plansCalendarBanner()}<div class="tabs" aria-label="Plan filters">${[['all','All plans'],['saved','Saved'],['rsvp','RSVPs']].map(([v,t])=>`<button data-tab="${v}" class="${v===planTab?'active':''}" aria-pressed="${v===planTab}">${t}</button>`).join('')}</div><div class="notice">Prototype only: RSVPs do not reserve a place or notify an organizer. Plans are stored in this browser.</div><section class="grid">${rows.length?rows.map(e=>card(e)).join(''):empty('Your next plan is waiting','Save an event or try a demo RSVP to build your week.','<a class="primary" href="#discover">Explore events ↗</a>')}</section>`;
 }else if(route==='preferences'){main.innerHTML=topLine()+`<div class="page-intro"><span class="eyebrow">START WITH WHAT YOU LOVE</span><h1>What’s your kind of thing?</h1><p>A few preferences help us put relevant events first. No personality tests. Change these anytime.</p></div><form id="prefs"><section class="panel"><h2>Your interests</h2><p>Choose as many as you like, or leave them open.</p><div class="choices">${categories.map(x=>`<label class="choice"><input type="checkbox" name="interest" value="${x}" ${state.prefs.interests.includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></section><section class="panel"><h2>Set the vibe</h2><p>These preferences change the order, so you can still discover something unexpected.</p><div class="prefs-grid"><label>Atmosphere<select name="atmosphere">${['Any','Relaxed','Social','Energetic'].map(x=>`<option ${state.prefs.atmosphere===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Budget preference<select name="budget">${['Any','Free'].map(x=>`<option ${state.prefs.budget===x?'selected':''}>${x}</option>`).join('')}</select></label></div></section><div class="notice">Your preferences stay in this browser. No account, location tracking, or student profile is created.</div><button class="primary" type="submit">Save & see suggestions ↗</button></form>`;
 }else{location.hash='discover';return}main.insertAdjacentHTML('beforeend','<p class="footer-note">SocialFinder · MIS 430, Group 1 · Independent student concept; not an official University of Alabama service.<br>All events, organizers, rooms and attendee examples are fictional and must not be used as real event information.</p>')}
function showEvent(id){const e=events.find(x=>x.id===id);if(!e)return;activeEvent=id;const rsvp=state.rsvps.includes(id),saved=state.saved.includes(id),together=state.together.includes(id);dialog.innerHTML=`<button class="close" aria-label="Close event details">×</button>${poster(e,'dialog-poster')}<div class="dialog-body"><p id="dialog-status" role="status" aria-live="polite"></p><span class="category">${e.category.toUpperCase()} · FICTIONAL EVENT</span><h2 id="dialog-title">${e.title}</h2><p>${e.description}</p><dl class="details"><div><dt>When</dt><dd>${weekday(e)}, November ${e.day}, 2026<br>${e.time} CT</dd></div><div><dt>Where</dt><dd>${e.location}</dd></div><div><dt>Cost</dt><dd>${money(e)}${e.cost?' · Materials included':''}</dd></div><div><dt>Attendance style</dt><dd>${e.drop?'Pop in or stay a while':'Plan to stay the full session'}</dd></div><div><dt>ACT Card</dt><dd>${e.act?'Required for entry':'Not required'}</dd></div><div><dt>Atmosphere</dt><dd>${e.atmosphere} · Newcomers welcome</dd></div></dl><h3>Know before you go</h3><p>${e.arrival}</p><p><strong>Accessibility:</strong> ${e.access}</p><p class="meta">Hosted by ${e.host} · Fictional organizer</p><div class="dialog-actions"><button class="primary" data-rsvp="${id}">${rsvp?'Cancel demo RSVP':'RSVP in demo'}</button><button class="secondary" data-save-dialog="${id}" aria-pressed="${saved}">${saved?'♥ Saved · remove':'♡ Save for later'}</button></div>${rsvp?'<p class="check" role="status">✓ Added to My plans. No real reservation was made.</p>':''}${calendarEventActions(e)}<div class="together"><h3>Going solo? Start together.</h3><p>Preview an optional small-group meetup. Nothing is sent, and no real students are shown.</p><label><input type="checkbox" id="together" ${together?'checked':''}><span>Opt in to the attend-together demo for this event. I understand this is a fictional preview with no sharing.</span></label>${together?'<div class="demo-people"><strong>Your fictional welcome group</strong><div class="people-avatars" aria-hidden="true"><span class="avatar">A</span><span class="avatar">J</span><span class="avatar">S</span></div>Alex, Jordan & Sam · Fictional examples<br>Meet at the event’s welcome point 10 minutes before start time.<br>Uncheck above to leave this demo group.</div>':''}</div></div>`;if(!dialog.open){opener=document.activeElement;dialog.showModal()}}
function toggleSave(id){if(state.saved.includes(id)){state.saved=state.saved.filter(x=>x!==id);toast('Removed from saved events')}else{state.saved.push(id);toast('Saved to My plans')}persist()}
function clearFilters(){filters={q:'',date:'Any',interest:'Any',cost:'Any',atmosphere:'Any'};render();document.getElementById('search')?.focus()}
document.addEventListener('click',ev=>{if(ev.target.closest('.skip-link')){ev.preventDefault();main.focus();return}const b=ev.target.closest('button');if(!b)return;if(b.dataset.open)showEvent(Number(b.dataset.open));if(b.dataset.save){toggleSave(Number(b.dataset.save));const id=b.dataset.save;render();(main.querySelector(`[data-save="${id}"]`)||main.querySelector('[data-tab]')||main).focus()}if(b.dataset.saveDialog){toggleSave(Number(b.dataset.saveDialog));render();showEvent(activeEvent);dialog.querySelector('[data-save-dialog]').focus();toast(state.saved.includes(activeEvent)?'Saved to My plans.':'Removed from saved events.')}if(b.dataset.rsvp){const id=Number(b.dataset.rsvp);state.rsvps=state.rsvps.includes(id)?state.rsvps.filter(x=>x!==id):[...state.rsvps,id];persist();render();showEvent(id);dialog.querySelector('[data-rsvp]').focus();toast(state.rsvps.includes(id)?'Demo RSVP added. No real reservation made.':'Demo RSVP cancelled')}if(b.classList.contains('close')&&b.closest('dialog')===dialog)dialog.close();if(b.dataset.tab){planTab=b.dataset.tab;render();main.querySelector(`[data-tab="${planTab}"]`)?.focus()}if(b.id==='clear'||b.id==='clear-empty')clearFilters();if(b.id==='reset'&&confirm('Clear all saved events, demo RSVPs, meetup choices, preferences and the mock calendar?')){state=defaultState();resetCalendar();persist();filters={q:'',date:'Any',interest:'Any',cost:'Any',atmosphere:'Any'};render();calendarNotice('Your demo has been reset')}});
document.addEventListener('input',ev=>{if(ev.target.id==='search'){filters.q=ev.target.value;renderResults()}});
document.addEventListener('change',ev=>{if(ev.target.dataset.filter){filters[ev.target.dataset.filter]=ev.target.value;renderResults()}if(ev.target.id==='together'){state.together=ev.target.checked?[...new Set([...state.together,activeEvent])]:state.together.filter(x=>x!==activeEvent);persist();render();showEvent(activeEvent);dialog.querySelector('#together').focus();toast(state.together.includes(activeEvent)?'Fictional meetup added to My plans.':'Left the fictional meetup.')}});
document.addEventListener('submit',ev=>{if(ev.target.id==='prefs'){ev.preventDefault();const fd=new FormData(ev.target);state.prefs={interests:fd.getAll('interest'),atmosphere:fd.get('atmosphere'),budget:fd.get('budget')};persist();location.hash='suggestions';toast('Preferences saved. Your suggestions are ready.')}});
dialog.addEventListener('click',ev=>{if(ev.target===dialog){const r=dialog.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)dialog.close()}});
dialog.addEventListener('close',()=>{if(opener?.isConnected)opener.focus();else (main.querySelector(`[data-open="${activeEvent}"]`)||main.querySelector('[data-tab]')||main).focus()});
window.addEventListener('hashchange',()=>{calendarModal().close();dialog.close();render();window.scrollTo(0,0);main.focus()});render();
